llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C50"],
      "claim": "Cladribine, a 2'-deoxyadenosine analogue with the highest Morgan similarity to the query, has human oral bioavailability of 35-55%, directly supporting F >= 20% for a purine 2'-deoxyriboside.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "Telbivudine, a 2'-deoxyriboside nucleoside analogue, has an absolute oral bioavailability of ~52% in humans, showing that polar deoxyriboside nucleosides can be adequately absorbed orally.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "D07001-F4, a 2'-deoxyuridine analogue, has a mean oral bioavailability of ~39% in patients, supporting oral absorption of deoxyriboside nucleosides despite high polarity.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "A cytidine-related nucleoside analogue showed ~50% oral bioavailability in patients, providing additional evidence that nucleoside analogues with similar physicochemical features can exceed the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Gemcitabine has low oral bioavailability (~10%) in humans, but this is attributed to cytidine deaminase-mediated first-pass metabolism, a liability not shared by the purine deoxyriboside query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The preponderance of direct human oral bioavailability data for structurally related 2'-deoxyribonucleosides, especially the purine analogue cladribine (35-55%), supports F >= 20% for the query deoxyguanosine. The main low-bioavailability analogue, gemcitabine, is low due to cytidine deaminase metabolism that is not relevant to this purine nucleoside. Physicochemical polarity is a concern, but transporter-mediated absorption and the modest 20% threshold make high the better-supported prediction.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for deoxyguanosine itself is available.",
    "Potential intestinal/hepatic purine nucleoside phosphorylase metabolism of deoxyguanosine is not directly captured by the analogue evidence.",
    "Exact nucleoside transporter and efflux transporter interactions for the query are not experimentally defined."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

